Use Node’s built-in `node:http` module with the `socketPath` request option:

```js
import { request } from 'node:http';

const req = request(
  {
    socketPath: '/tmp/example-node.sock',
    path: '/',
  },
  (res) => {
    let body = '';

    res.on('data', (chunk) => {
      body += chunk;
    });

    res.on('end', () => {
      console.log(body);
    });
  },
);

req.on('error', console.error);
req.end();
```

The server can listen on the same Unix socket path:

```js
import { createServer } from 'node:http';

const server = createServer((_req, res) => {
  res.end('Hello from node:http');
});

server.listen('/tmp/example-node.sock');
```

For a Unix-domain-socket request, use `socketPath` and provide the HTTP request `path`.
